  .form-row { grid-template-columns: 1fr; }
  .form-card { padding: 24px; }

  .cookie-banner {
    flex-direction: column;
    text-align: center;
    padding: 20px;
    gap: 14px;
  }

  .lifecycle-flow {
    flex-direction: column;
    align-items: center;
    gap: 24px;
  }

  .lifecycle-flow::before { display: none; }

