/* ============================================
   WellStream Platform — Shared Styles
   ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

:root {
  --navy-deep: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #233044;
  --teal: #00B4D8;
  --teal-dark: #0096B4;
  --blue: #0077B6;
  --blue-dark: #005A8C;
  --green: #6CC24A;
  --green-dark: #5AA83C;
  --white: #FFFFFF;
  --text-primary: #E8ECF1;
  --text-secondary: #9BA4B5;
  --text-muted: #6B7485;
  --border: #2A3A4E;
  --border-light: #334455;
  --gradient-dark: linear-gradient(135deg, #0D1B2A 0%, #152238 100%);
  --gradient-accent: linear-gradient(135deg, #00B4D8 0%, #0077B6 100%);
  --gradient-green: linear-gradient(135deg, #6CC24A 0%, #4A9A2E 100%);
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.5);
  --shadow-glow: 0 0 20px rgba(0,180,216,0.15);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background-color: var(--navy-deep);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input, textarea, select { font-family: inherit; }

/* Container */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ============================================
   Navigation
   ============================================ */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  transition: background var(--transition);
}

.nav.scrolled {
  background: rgba(13, 27, 42, 0.98);
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
}

.nav-logo-icon {
  width: 36px;
  height: 36px;
  background: var(--gradient-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  font-size: 1.1rem;
  color: var(--white);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-link {
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition);
}

.nav-link:hover { color: var(--white); background: rgba(255,255,255,0.05); }
.nav-link.active { color: var(--teal); }

/* Dropdown */
.nav-dropdown {
  position: relative;
}

.nav-dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition);
  cursor: pointer;
  background: none;
  border: none;
}

.nav-dropdown-toggle:hover { color: var(--white); background: rgba(255,255,255,0.05); }
.nav-dropdown-toggle svg { width: 14px; height: 14px; transition: transform var(--transition); }
.nav-dropdown.open .nav-dropdown-toggle svg { transform: rotate(180deg); }

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  min-width: 200px;
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 6px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition);
  box-shadow: var(--shadow-lg);
}

.nav-dropdown.open .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown-item {
  display: block;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.88rem;
  transition: all var(--transition);
}

.nav-dropdown-item:hover { color: var(--white); background: rgba(255,255,255,0.06); }

/* CTA Button */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--gradient-accent);
  color: var(--white);
  box-shadow: 0 2px 12px rgba(0,180,216,0.25);
}

.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 20px rgba(0,180,216,0.35);
}

.btn-secondary {
  background: rgba(255,255,255,0.08);
  color: var(--white);
  border: 1px solid var(--border);
}

.btn-secondary:hover { background: rgba(255,255,255,0.12); border-color: var(--border-light); }

.btn-outline {
  background: transparent;
  color: var(--teal);
  border: 1.5px solid var(--teal);
}

.btn-outline:hover { background: rgba(0,180,216,0.08); }

.btn-lg { padding: 16px 32px; font-size: 1rem; }
.btn-sm { padding: 8px 16px; font-size: 0.82rem; }

.nav .btn { padding: 10px 20px; font-size: 0.85rem; }

/* Mobile Nav */
.nav-mobile-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-primary);
}

.nav-mobile-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: currentColor;
  position: relative;
  transition: all var(--transition);
}

.nav-mobile-toggle span::before,
.nav-mobile-toggle span::after {
  content: '';
  position: absolute;
  width: 22px;
  height: 2px;
  background: currentColor;
  transition: all var(--transition);
}

.nav-mobile-toggle span::before { top: -7px; }
.nav-mobile-toggle span::after { top: 7px; }

/* ============================================
   Hero Sections
   ============================================ */

.hero {
  padding: 120px 0 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 600px;
  background: radial-gradient(circle at center, rgba(0,180,216,0.06) 0%, transparent 70%);
  pointer-events: none;
}

.hero-label {
  display: inline-block;
  padding: 6px 16px;
  background: rgba(0,180,216,0.1);
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: 100px;
  color: var(--teal);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 24px;
}

.hero h1 {
  font-size: 3.25rem;
  font-weight: 900;
  line-height: 1.12;
  letter-spacing: -0.03em;
  max-width: 800px;
  margin: 0 auto 20px;
  color: var(--white);
}

.hero p {
  font-size: 1.2rem;
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto 36px;
  line-height: 1.65;
}

.hero-actions {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-page {
  padding: 120px 0 60px;
  text-align: left;
}

.hero-page h1 {
  font-size: 2.75rem;
  max-width: 700px;
  margin: 0 0 16px;
  text-align: left;
}

.hero-page p {
  margin: 0 0 28px;
  text-align: left;
  max-width: 560px;
}

.hero-page .hero-actions { justify-content: flex-start; }

/* ============================================
   Section Headers
   ============================================ */

.section {
  padding: 80px 0;
}

.section-label {
  display: inline-block;
  padding: 5px 14px;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 100px;
  color: var(--green);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.section-header {
  margin-bottom: 48px;
}

.section-header.center { text-align: center; }

.section-header h2 {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--white);
  margin-bottom: 14px;
}

.section-header p {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 620px;
  line-height: 1.65;
}

.section-header.center p { margin: 0 auto; }

/* ============================================
   Use Cases Grid
   ============================================ */

.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.use-case-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
  cursor: pointer;
}

.use-case-card:hover {
  border-color: var(--teal);
  transform: translateY(-2px);
  box-shadow: var(--shadow-glow);
}

.use-case-icon {
  width: 44px;
  height: 44px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--teal);
  font-size: 1.3rem;
}

.use-case-card h3 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}

.use-case-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ============================================
   Industry Tabs
   ============================================ */

.tabs-nav {
  display: flex;
  gap: 4px;
  background: var(--navy-mid);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 32px;
  overflow-x: auto;
  border: 1px solid var(--border);
}

.tab-btn {
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.88rem;
  font-weight: 500;
  transition: all var(--transition);
  white-space: nowrap;
}

.tab-btn:hover { color: var(--white); }
.tab-btn.active { background: var(--teal); color: var(--white); }

.tabs-content { position: relative; }

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active { display: block; }

.tab-panel-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.tab-panel-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 22px;
}

.tab-panel-card h4 {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 6px;
}

.tab-panel-card p {
  font-size: 0.84rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ============================================
   Platform Ecosystem Diagram
   ============================================ */

.ecosystem-diagram {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.eco-pillar {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  position: relative;
  transition: all var(--transition);
}

.eco-pillar:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-glow);
}

.eco-pillar-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 18px;
  background: rgba(0,180,216,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.6rem;
  border: 2px solid rgba(0,180,216,0.2);
}

.eco-pillar:nth-child(2) .eco-pillar-icon { background: rgba(108,194,74,0.1); border-color: rgba(108,194,74,0.2); color: var(--green); }
.eco-pillar:nth-child(3) .eco-pillar-icon { background: rgba(0,119,182,0.1); border-color: rgba(0,119,182,0.2); color: var(--blue); }

.eco-pillar h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}

.eco-pillar p {
  font-size: 0.88rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.eco-connector {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

.eco-connector::after {
  content: '';
  display: block;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, var(--teal), var(--green));
  border-radius: 2px;
}

/* ============================================
   Featured Product Banner
   ============================================ */

.featured-banner {
  background: var(--gradient-dark);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: flex;
  align-items: center;
  gap: 40px;
  margin: 60px 0;
}

.featured-badge {
  display: inline-block;
  padding: 5px 14px;
  background: rgba(0,180,216,0.15);
  border-radius: 100px;
  color: var(--teal);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.featured-banner h3 {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 8px;
}

.featured-banner p {
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* ============================================
   Stats Circles
   ============================================ */

.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.stat-circle {
  text-align: center;
}

.stat-ring {
  position: relative;
  width: 140px;
  height: 140px;
  margin: 0 auto 16px;
}

.stat-ring svg {
  transform: rotate(-90deg);
}

.stat-ring-bg {
  fill: none;
  stroke: var(--navy-light);
  stroke-width: 8;
}

.stat-ring-fill {
  fill: none;
  stroke-width: 8;
  stroke-linecap: round;
  transition: stroke-dashoffset 1.5s ease;
}

.stat-ring-value {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-weight: 900;
  color: var(--white);
}

.stat-label {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

/* ============================================
   Implementation Timeline
   ============================================ */

.timeline {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.timeline-item {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
}

.timeline-time {
  font-size: 1.5rem;
  font-weight: 900;
  color: var(--teal);
  margin-bottom: 4px;
}

.timeline-desc {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 16px;
}

.progress-bar {
  height: 6px;
  background: var(--navy-light);
  border-radius: 3px;
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  border-radius: 3px;
  background: var(--gradient-accent);
  transition: width 1.2s ease;
}

/* ============================================
   Accordion
   ============================================ */

.accordion { display: flex; flex-direction: column; gap: 12px; }

.accordion-item {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 28px;
  cursor: pointer;
  transition: all var(--transition);
}

.accordion-header:hover { background: rgba(255,255,255,0.02); }

.accordion-header h3 {
  font-size: 1.08rem;
  font-weight: 700;
  color: var(--white);
}

.accordion-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--teal);
  transition: transform var(--transition);
  flex-shrink: 0;
}

.accordion-item.open .accordion-icon { transform: rotate(45deg); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.accordion-item.open .accordion-body {
  max-height: 200px;
  padding: 0 28px 22px;
}

.accordion-body p {
  font-size: 0.92rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   Testimonial Carousel
   ============================================ */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel-slide {
  flex: 0 0 100%;
  padding: 0 4px;
}

.testimonial-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 36px;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  color: var(--text-primary);
  line-height: 1.65;
  font-style: italic;
  margin-bottom: 20px;
}

.testimonial-quote::before { content: '\201C'; font-size: 3rem; color: var(--teal); display: block; line-height: 1; margin-bottom: 8px; }

.testimonial-author {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--white);
  margin-bottom: 2px;
}

.testimonial-role {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--navy-light);
  cursor: pointer;
  transition: all var(--transition);
}

.carousel-dot.active { background: var(--teal); width: 32px; border-radius: 10px; }

/* ============================================
   Security Page
   ============================================ */

.security-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
}

.security-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
}

.security-card-icon {
  width: 44px;
  height: 44px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  color: var(--teal);
  font-size: 1.2rem;
}

.security-card h4 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}

.security-card p {
  font-size: 0.88rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.compliance-cta {
  background: var(--gradient-dark);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 48px;
  text-align: center;
  margin-top: 40px;
}

.compliance-cta h3 {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 12px;
}

.compliance-cta p {
  color: var(--text-secondary);
  margin-bottom: 24px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ============================================
   Integration Page
   ============================================ */

.etl-benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.etl-benefit-card {
  display: flex;
  gap: 16px;
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
}

.etl-benefit-check {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(108,194,74,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  flex-shrink: 0;
}

.etl-benefit-card h4 {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 6px;
}

.etl-benefit-card p {
  font-size: 0.86rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ============================================
   Demo Form
   ============================================ */

.demo-section {
  padding: 120px 0 80px;
}

.demo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: start;
}

.demo-info h2 {
  font-size: 2rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 14px;
}

.demo-info p {
  color: var(--text-secondary);
  line-height: 1.65;
  margin-bottom: 32px;
}

.demo-features {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.demo-feature {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.demo-feature-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--teal);
  flex-shrink: 0;
  font-size: 0.85rem;
}

.demo-feature h4 {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--white);
  margin-bottom: 2px;
}

.demo-feature p {
  font-size: 0.82rem;
  color: var(--text-muted);
  margin-bottom: 0;
}

.form-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 40px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.form-group {
  margin-bottom: 18px;
}

.form-group label {
  display: block;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 12px 16px;
  background: var(--navy-deep);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.9rem;
  transition: border-color var(--transition);
  outline: none;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.1);
}

.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: #e74c3c;
}

.form-error {
  font-size: 0.75rem;
  color: #e74c3c;
  margin-top: 4px;
  display: none;
}

.form-error.visible { display: block; }

.form-group textarea { resize: vertical; min-height: 100px; }

.form-submit {
  width: 100%;
  padding: 14px;
  background: var(--gradient-accent);
  color: var(--white);
  font-size: 0.95rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
  margin-top: 8px;
}

.form-submit:hover {
  box-shadow: 0 4px 20px rgba(0,180,216,0.35);
  transform: translateY(-1px);
}

.form-success {
  display: none;
  background: rgba(108,194,74,0.1);
  border: 1px solid var(--green);
  border-radius: var(--radius-md);
  padding: 20px;
  text-align: center;
  color: var(--green);
  font-weight: 600;
  margin-top: 16px;
}

.form-success.visible { display: block; }

/* ============================================
   Support Contact
   ============================================ */

.support-section {
  padding: 60px 0 80px;
}

.support-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.support-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  text-align: center;
}

.support-card-icon {
  font-size: 1.5rem;
  margin-bottom: 12px;
}

.support-card h4 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 6px;
}

.support-card p {
  font-size: 0.86rem;
  color: var(--text-secondary);
}

/* ============================================
   Cookie Banner
   ============================================ */

.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px 28px;
  display: flex;
  align-items: center;
  gap: 24px;
  z-index: 999;
  box-shadow: var(--shadow-lg);
  max-width: 640px;
  width: calc(100% - 48px);
}

.cookie-banner p {
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.cookie-banner p a {
  color: var(--teal);
  text-decoration: underline;
}

.cookie-actions {
  display: flex;
  gap: 10px;
  flex-shrink: 0;
}

/* ============================================
   Culture / Renewables CTAs
   ============================================ */

.split-cta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 40px;
}

.cta-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 40px;
  transition: all var(--transition);
}

.cta-card:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-glow);
}

.cta-card h3 {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 10px;
}

.cta-card p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
  margin-bottom: 20px;
}

/* ============================================
   Data Lifecycle Diagram (Platform Overview)
   ============================================ */

.lifecycle-diagram {
  position: relative;
  padding: 20px 0;
}

.lifecycle-flow {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  position: relative;
}

.lifecycle-flow::before {
  content: '';
  position: absolute;
  top: 40px;
  left: 8%;
  right: 8%;
  height: 2px;
  background: linear-gradient(90deg, var(--teal), var(--green), var(--blue));
  z-index: 0;
}

.lifecycle-node {
  text-align: center;
  position: relative;
  z-index: 1;
  flex: 1;
  max-width: 200px;
}

.lifecycle-node-dot {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  margin: 0 auto 16px;
  border: 3px solid var(--teal);
  background: var(--navy-deep);
}

.lifecycle-node:nth-child(2) .lifecycle-node-dot { border-color: var(--green); }
.lifecycle-node:nth-child(3) .lifecycle-node-dot { border-color: #4ECDC4; }
.lifecycle-node:nth-child(4) .lifecycle-node-dot { border-color: var(--blue); }
.lifecycle-node:nth-child(5) .lifecycle-node-dot { border-color: #A78BFA; }

.lifecycle-node h4 {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 4px;
}

.lifecycle-node p {
  font-size: 0.78rem;
  color: var(--text-muted);
  line-height: 1.4;
}

/* ============================================
   Footer
   ============================================ */

.footer {
  background: var(--navy-mid);
  border-top: 1px solid var(--border);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 40px;
}

.footer-brand p {
  font-size: 0.88rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin-top: 16px;
  max-width: 280px;
}

.footer-col h4 {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.88rem;
  color: var(--text-muted);
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.82rem;
  color: var(--text-muted);
}

/* ============================================
   Animations
   ============================================ */

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: fadeInUp 0.6s ease forwards;
}

/* ============================================
   Responsive
   ============================================ */

@media (max-width: 1024px) {
  .hero h1 { font-size: 2.5rem; }
  .hero-page h1 { font-size: 2.2rem; }
  .use-cases-grid { grid-template-columns: repeat(2, 1fr); }
  .ecosystem-diagram { grid-template-columns: 1fr; }
  .timeline { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .demo-grid { grid-template-columns: 1fr; gap: 40px; }
  .split-cta { grid-template-columns: 1fr; }
  .stats-row { grid-template-columns: repeat(3, 1fr); gap: 16px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-mobile-toggle { display: flex; }

  .nav.open .nav-links {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px;
    left: 0;
    width: 100%;
    background: var(--navy-mid);
    border-bottom: 1px solid var(--border);
    padding: 16px 24px;
    gap: 4px;
  }

  .nav.open .nav-links .nav-link,
  .nav.open .nav-links .nav-dropdown-toggle {
    width: 100%;
    text-align: left;
    padding: 12px 16px;
  }

  .nav.open .nav-dropdown-menu {
    position: static;
    opacity: 1;
    visibility: visible;
    transform: none;
    box-shadow: none;
    background: rgba(0,0,0,0.2);
    margin-top: 4px;
  }

  .hero { padding: 100px 0 60px; }
  .hero h1 { font-size: 2rem; }
  .hero-page h1 { font-size: 1.8rem; }
  .hero p { font-size: 1rem; }

  .use-cases-grid { grid-template-columns: 1fr; }
  .etl-benefits-grid { grid-template-columns: 1fr; }
  .tabs-nav { gap: 0; }
  .tab-btn { font-size: 0.78rem; padding: 8px 14px; }

  .featured-banner {
    flex-direction: column;
    text-align: center;
    padding: 32px 24px;
  }

  .stats-row { grid-template-columns: 1fr; }
  .timeline { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }

  .form-row { grid-template-columns: 1fr; }
  .form-card { padding: 24px; }

  .cookie-banner {
    flex-direction: column;
    text-align: center;
    padding: 20px;
    gap: 14px;
  }

  .lifecycle-flow {
    flex-direction: column;
    align-items: center;
    gap: 24px;
  }

  .lifecycle-flow::before { display: none; }

  .support-grid { grid-template-columns: 1fr; }

  .tab-panel-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 1.65rem; }
  .section-header h2 { font-size: 1.5rem; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; }
}

/* ============================================
   WellStream Platform — Shared Styles
   ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

:root {
  --navy-deep: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #233044;
  --teal: #00B4D8;
  --teal-dark: #0096B4;
  --blue: #0077B6;
  --blue-dark: #005A8C;
  --green: #6CC24A;
  --green-dark: #5AA83C;
  --white: #FFFFFF;
  --text-primary: #E8ECF1;
  --text-secondary: #9BA4B5;
  --text-muted: #6B7485;
  --border: #2A3A4E;
  --border-light: #334455;
  --gradient-dark: linear-gradient(135deg, #0D1B2A 0%, #152238 100%);
  --gradient-accent: linear-gradient(135deg, #00B4D8 0%, #0077B6 100%);
  --gradient-green: linear-gradient(135deg, #6CC24A 0%, #4A9A2E 100%);
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.5);
  --shadow-glow: 0 0 20px rgba(0,180,216,0.15);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background-color: var(--navy-deep);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input, textarea, select { font-family: inherit; }

/* Container */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ============================================
   Navigation
   ============================================ */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  transition: background var(--transition);
}

.nav.scrolled {
  background: rgba(13, 27, 42, 0.98);
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
}

.nav-logo-icon {
  width: 36px;
  height: 36px;
  background: var(--gradient-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  font-size: 1.1rem;
  color: var(--white);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-link {
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition);
}

.nav-link:hover { color: var(--white); background: rgba(255,255,255,0.05); }
.nav-link.active { color: var(--teal); }

/* Dropdown */
.nav-dropdown {
  position: relative;
}

.nav-dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition);
  cursor: pointer;
  background: none;
  border: none;
}

.nav-dropdown-toggle:hover { color: var(--white); background: rgba(255,255,255,0.05); }
.nav-dropdown-toggle svg { width: 14px; height: 14px; transition: transform var(--transition); }
.nav-dropdown.open .nav-dropdown-toggle svg { transform: rotate(180deg); }

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  min-width: 200px;
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 6px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition);
  box-shadow: var(--shadow-lg);
}

.nav-dropdown.open .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown-item {
  display: block;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.88rem;
  transition: all var(--transition);
}

.nav-dropdown-item:hover { color: var(--white); background: rgba(255,255,255,0.06); }

/* CTA Button */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--gradient-accent);
  color: var(--white);
  box-shadow: 0 2px 12px rgba(0,180,216,0.25);
}

.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 20px rgba(0,180,216,0.35);
}

.btn-secondary {
  background: rgba(255,255,255,0.08);
  color: var(--white);
  border: 1px solid var(--border);
}

.btn-secondary:hover { background: rgba(255,255,255,0.12); border-color: var(--border-light); }

.btn-outline {
  background: transparent;
  color: var(--teal);
  border: 1.5px solid var(--teal);
}

.btn-outline:hover { background: rgba(0,180,216,0.08); }

.btn-lg { padding: 16px 32px; font-size: 1rem; }
.btn-sm { padding: 8px 16px; font-size: 0.82rem; }

.nav .btn { padding: 10px 20px; font-size: 0.85rem; }

/* Mobile Nav */
.nav-mobile-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-primary);
}

.nav-mobile-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: currentColor;
  position: relative;
  transition: all var(--transition);
}

.nav-mobile-toggle span::before,
.nav-mobile-toggle span::after {
  content: '';
  position: absolute;
  width: 22px;
  height: 2px;
  background: currentColor;
  transition: all var(--transition);
}

.nav-mobile-toggle span::before { top: -7px; }
.nav-mobile-toggle span::after { top: 7px; }

/* ============================================
   Hero Sections
   ============================================ */

.hero {
  padding: 120px 0 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 600px;
  background: radial-gradient(circle at center, rgba(0,180,216,0.06) 0%, transparent 70%);
  pointer-events: none;
}

.hero-label {
  display: inline-block;
  padding: 6px 16px;
  background: rgba(0,180,216,0.1);
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: 100px;
  color: var(--teal);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 24px;
}

.hero h1 {
  font-size: 3.25rem;
  font-weight: 900;
  line-height: 1.12;
  letter-spacing: -0.03em;
  max-width: 800px;
  margin: 0 auto 20px;
  color: var(--white);
}

.hero p {
  font-size: 1.2rem;
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto 36px;
  line-height: 1.65;
}

.hero-actions {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-page {
  padding: 120px 0 60px;
  text-align: left;
}

.hero-page h1 {
  font-size: 2.75rem;
  max-width: 700px;
  margin: 0 0 16px;
  text-align: left;
}

.hero-page p {
  margin: 0 0 28px;
  text-align: left;
  max-width: 560px;
}

.hero-page .hero-actions { justify-content: flex-start; }

/* ============================================
   Section Headers
   ============================================ */

.section {
  padding: 80px 0;
}

.section-label {
  display: inline-block;
  padding: 5px 14px;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 100px;
  color: var(--green);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.section-header {
  margin-bottom: 48px;
}

.section-header.center { text-align: center; }

.section-header h2 {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--white);
  margin-bottom: 14px;
}

.section-header p {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 620px;
  line-height: 1.65;
}

.section-header.center p { margin: 0 auto; }

/* ============================================
   Use Cases Grid
   ============================================ */

.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.use-case-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
  cursor: pointer;
}

.use-case-card:hover {
  border-color: var(--teal);
  transform: translateY(-2px);
  box-shadow: var(--shadow-glow);
}

.use-case-icon {
  width: 44px;
  height: 44px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--teal);
  font-size: 1.3rem;
}

.use-case-card h3 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}

.use-case-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ============================================
   Industry Tabs
   ============================================ */

.tabs-nav {
  display: flex;
  gap: 4px;
  background: var(--navy-mid);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 32px;
  overflow-x: auto;
  border: 1px solid var(--border);
}

.tab-btn {
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.88rem;
  font-weight: 500;
  transition: all var(--transition);
  white-space: nowrap;
}

.tab-btn:hover { color: var(--white); }
.tab-btn.active { background: var(--teal); color: var(--white); }

.tabs-content { position: relative; }

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active { display: block; }

.tab-panel-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.tab-panel-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 22px;
}

.tab-panel-card h4 {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 6px;
}

.tab-panel-card p {
  font-size: 0.84rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ============================================
   Platform Ecosystem Diagram
   ============================================ */

.ecosystem-diagram {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.eco-pillar {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  position: relative;
  transition: all var(--transition);
}

.eco-pillar:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-glow);
}

.eco-pillar-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 18px;
  background: rgba(0,180,216,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.6rem;
  border: 2px solid rgba(0,180,216,0.2);
}

.eco-pillar:nth-child(2) .eco-pillar-icon { background: rgba(108,194,74,0.1); border-color: rgba(108,194,74,0.2); color: var(--green); }
.eco-pillar:nth-child(3) .eco-pillar-icon { background: rgba(0,119,182,0.1); border-color: rgba(0,119,182,0.2); color: var(--blue); }

.eco-pillar h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}

.eco-pillar p {
  font-size: 0.88rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.eco-connector {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

.eco-connector::after {
  content: '';
  display: block;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, var(--teal), var(--green));
  border-radius: 2px;
}

/* ============================================
   Featured Product Banner
   ============================================ */

.featured-banner {
  background: var(--gradient-dark);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: flex;
  align-items: center;
  gap: 40px;
  margin: 60px 0;
}

.featured-badge {
  display: inline-block;
  padding: 5px 14px;
  background: rgba(0,180,216,0.15);
  border-radius: 100px;
  color: var(--teal);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.featured-banner h3 {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 8px;
}

.featured-banner p {
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* ============================================
   Stats Circles
   ============================================ */

.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.stat-circle {
  text-align: center;
}

.stat-ring {
  position: relative;
  width: 140px;
  height: 140px;
  margin: 0 auto 16px;
}

.stat-ring svg {
  transform: rotate(-90deg);
}

.stat-ring-bg {
  fill: none;
  stroke: var(--navy-light);
  stroke-width: 8;
}

.stat-ring-fill {
  fill: none;
  stroke-width: 8;
  stroke-linecap: round;
  transition: stroke-dashoffset 1.5s ease;
}

.stat-ring-value {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-weight: 900;
  color: var(--white);
}

.stat-label {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

/* ============================================
   Implementation Timeline
   ============================================ */

.timeline {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.timeline-item {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
}

.timeline-time {
  font-size: 1.5rem;
  font-weight: 900;
  color: var(--teal);
  margin-bottom: 4px;
}

.timeline-desc {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 16px;
}

.progress-bar {
  height: 6px;
  background: var(--navy-light);
  border-radius: 3px;
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  border-radius: 3px;
  background: var(--gradient-accent);
  transition: width 1.2s ease;
}

/* ============================================
   Accordion
   ============================================ */

.accordion { display: flex; flex-direction: column; gap: 12px; }

.accordion-item {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 28px;
  cursor: pointer;
  transition: all var(--transition);
}

.accordion-header:hover { background: rgba(255,255,255,0.02); }

.accordion-header h3 {
  font-size: 1.08rem;
  font-weight: 700;
  color: var(--white);
}

.accordion-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--teal);
  transition: transform var(--transition);
  flex-shrink: 0;
}

.accordion-item.open .accordion-icon { transform: rotate(45deg); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.accordion-item.open .accordion-body {
  max-height: 200px;
  padding: 0 28px 22px;
}

.accordion-body p {
  font-size: 0.92rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   Testimonial Carousel
   ============================================ */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel-slide {
  flex: 0 0 100%;
  padding: 0 4px;
}

.testimonial-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 36px;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  color: var(--text-primary);
  line-height: 1.65;
  font-style: italic;
  margin-bottom: 20px;
}

.testimonial-quote::before { content: '\201C'; font-size: 3rem; color: var(--teal); display: block; line-height: 1; margin-bottom: 8px; }

.testimonial-author {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--white);
  margin-bottom: 2px;
}

.testimonial-role {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--navy-light);
  cursor: pointer;
  transition: all var(--transition);
}

.carousel-dot.active { background: var(--teal); width: 32px; border-radius: 10px; }

/* ============================================
   Security Page
   ============================================ */

.security-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
}

.security-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
}

.security-card-icon {
  width: 44px;
  height: 44px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  color: var(--teal);
  font-size: 1.2rem;
}

.security-card h4 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}

.security-card p {
  font-size: 0.88rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.compliance-cta {
  background: var(--gradient-dark);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 48px;
  text-align: center;
  margin-top: 40px;
}

.compliance-cta h3 {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 12px;
}

.compliance-cta p {
  color: var(--text-secondary);
  margin-bottom: 24px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ============================================
   Integration Page
   ============================================ */

.etl-benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.etl-benefit-card {
  display: flex;
  gap: 16px;
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
}

.etl-benefit-check {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(108,194,74,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  flex-shrink: 0;
}

.etl-benefit-card h4 {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 6px;
}

.etl-benefit-card p {
  font-size: 0.86rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ============================================
   Demo Form
   ============================================ */

.demo-section {
  padding: 120px 0 80px;
}

.demo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: start;
}

.demo-info h2 {
  font-size: 2rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 14px;
}

.demo-info p {
  color: var(--text-secondary);
  line-height: 1.65;
  margin-bottom: 32px;
}

.demo-features {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.demo-feature {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.demo-feature-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--teal);
  flex-shrink: 0;
  font-size: 0.85rem;
}

.demo-feature h4 {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--white);
  margin-bottom: 2px;
}

.demo-feature p {
  font-size: 0.82rem;
  color: var(--text-muted);
  margin-bottom: 0;
}

.form-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 40px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.form-group {
  margin-bottom: 18px;
}

.form-group label {
  display: block;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 12px 16px;
  background: var(--navy-deep);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.9rem;
  transition: border-color var(--transition);
  outline: none;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.1);
}

.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: #e74c3c;
}

.form-error {
  font-size: 0.75rem;
  color: #e74c3c;
  margin-top: 4px;
  display: none;
}

.form-error.visible { display: block; }

.form-group textarea { resize: vertical; min-height: 100px; }

.form-submit {
  width: 100%;
  padding: 14px;
  background: var(--gradient-accent);
  color: var(--white);
  font-size: 0.95rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
  margin-top: 8px;
}

.form-submit:hover {
  box-shadow: 0 4px 20px rgba(0,180,216,0.35);
  transform: translateY(-1px);
}

.form-success {
  display: none;
  background: rgba(108,194,74,0.1);
  border: 1px solid var(--green);
  border-radius: var(--radius-md);
  padding: 20px;
  text-align: center;
  color: var(--green);
  font-weight: 600;
  margin-top: 16px;
}

.form-success.visible { display: block; }

/* ============================================
   Support Contact
   ============================================ */

.support-section {
  padding: 60px 0 80px;
}

.support-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.support-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  text-align: center;
}

.support-card-icon {
  font-size: 1.5rem;
  margin-bottom: 12px;
}

.support-card h4 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 6px;
}

.support-card p {
  font-size: 0.86rem;
  color: var(--text-secondary);
}

/* ============================================
   Cookie Banner
   ============================================ */

.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px 28px;
  display: flex;
  align-items: center;
  gap: 24px;
  z-index: 999;
  box-shadow: var(--shadow-lg);
  max-width: 640px;
  width: calc(100% - 48px);
}

.cookie-banner p {
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.cookie-banner p a {
  color: var(--teal);
  text-decoration: underline;
}

.cookie-actions {
  display: flex;
  gap: 10px;
  flex-shrink: 0;
}

/* ============================================
   Culture / Renewables CTAs
   ============================================ */

.split-cta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 40px;
}

.cta-card {
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 40px;
  transition: all var(--transition);
}

.cta-card:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-glow);
}

.cta-card h3 {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 10px;
}

.cta-card p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
  margin-bottom: 20px;
}

/* ============================================
   Data Lifecycle Diagram (Platform Overview)
   ============================================ */

.lifecycle-diagram {
  position: relative;
  padding: 20px 0;
}

.lifecycle-flow {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  position: relative;
}

.lifecycle-flow::before {
  content: '';
  position: absolute;
  top: 40px;
  left: 8%;
  right: 8%;
  height: 2px;
  background: linear-gradient(90deg, var(--teal), var(--green), var(--blue));
  z-index: 0;
}

.lifecycle-node {
  text-align: center;
  position: relative;
  z-index: 1;
  flex: 1;
  max-width: 200px;
}

.lifecycle-node-dot {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  margin: 0 auto 16px;
  border: 3px solid var(--teal);
  background: var(--navy-deep);
}

.lifecycle-node:nth-child(2) .lifecycle-node-dot { border-color: var(--green); }
.lifecycle-node:nth-child(3) .lifecycle-node-dot { border-color: #4ECDC4; }
.lifecycle-node:nth-child(4) .lifecycle-node-dot { border-color: var(--blue); }
.lifecycle-node:nth-child(5) .lifecycle-node-dot { border-color: #A78BFA; }

.lifecycle-node h4 {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 4px;
}

.lifecycle-node p {
  font-size: 0.78rem;
  color: var(--text-muted);
  line-height: 1.4;
}

/* ============================================
   Footer
   ============================================ */

.footer {
  background: var(--navy-mid);
  border-top: 1px solid var(--border);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 40px;
}

.footer-brand p {
  font-size: 0.88rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin-top: 16px;
  max-width: 280px;
}

.footer-col h4 {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.88rem;
  color: var(--text-muted);
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.82rem;
  color: var(--text-muted);
}

/* ============================================
   Animations
   ============================================ */

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: fadeInUp 0.6s ease forwards;
}

/* ============================================
   Responsive
   ============================================ */

@media (max-width: 1024px) {
  .hero h1 { font-size: 2.5rem; }
  .hero-page h1 { font-size: 2.2rem; }
  .use-cases-grid { grid-template-columns: repeat(2, 1fr); }
  .ecosystem-diagram { grid-template-columns: 1fr; }
  .timeline { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .demo-grid { grid-template-columns: 1fr; gap: 40px; }
  .split-cta { grid-template-columns: 1fr; }
  .stats-row { grid-template-columns: repeat(3, 1fr); gap: 16px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-mobile-toggle { display: flex; }

  .nav.open .nav-links {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px;
    left: 0;
    width: 100%;
    background: var(--navy-mid);
    border-bottom: 1px solid var(--border);
    padding: 16px 24px;
    gap: 4px;
  }

  .nav.open .nav-links .nav-link,
  .nav.open .nav-links .nav-dropdown-toggle {
    width: 100%;
    text-align: left;
    padding: 12px 16px;
  }

  .nav.open .nav-dropdown-menu {
    position: static;
    opacity: 1;
    visibility: visible;
    transform: none;
    box-shadow: none;
    background: rgba(0,0,0,0.2);
    margin-top: 4px;
  }

  .hero { padding: 100px 0 60px; }
  .hero h1 { font-size: 2rem; }
  .hero-page h1 { font-size: 1.8rem; }
  .hero p { font-size: 1rem; }

  .use-cases-grid { grid-template-columns: 1fr; }
  .etl-benefits-grid { grid-template-columns: 1fr; }
  .tabs-nav { gap: 0; }
  .tab-btn { font-size: 0.78rem; padding: 8px 14px; }

  .featured-banner {
    flex-direction: column;
    text-align: center;
    padding: 32px 24px;
  }

  .stats-row { grid-template-columns: 1fr; }
  .timeline { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }

  .form-row { grid-template-columns: 1fr; }
  .form-card { padding: 24px; }

  .cookie-banner {
    flex-direction: column;
    text-align: center;
    padding: 20px;
    gap: 14px;
  }

  .lifecycle-flow {
    flex-direction: column;
    align-items: center;
    gap: 24px;
  }

  .lifecycle-flow::before { display: none; }

  .support-grid { grid-template-columns: 1fr; }

  .tab-panel-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 1.65rem; }
  .section-header h2 { font-size: 1.5rem; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; }
}

